// Package db is factory's Postgres layer: the connection pool, the embedded
// golang-migrate migrations, and the queries sqlc generates from sql/queries.
//
// It holds no business rules. Which rows may change and how is decided by the
// service packages that call it (internal/work). Postgres is the only store;
// there is no SQLite. The *.sql.go, db.go and models.go files are generated by
// `make generate/sqlc` and must not be edited by hand.
package db

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
)

// DatabaseURLEnv names the environment variable that holds the Postgres URL.
const DatabaseURLEnv = "FACTORY_DATABASE_URL"

// ErrNoDatabaseURL is returned when no database URL was given.
var ErrNoDatabaseURL = errors.New("no database URL: set " + DatabaseURLEnv + " or pass --database-url")

// Open returns a connection pool for databaseURL and checks that the server
// answers.
func Open(ctx context.Context, databaseURL string) (*pgxpool.Pool, error) {
	if databaseURL == "" {
		return nil, ErrNoDatabaseURL
	}
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("reach database (is Postgres running? `make serve/postgres` starts one locally): %w", err)
	}
	return pool, nil
}
